// One-time-use offer codes: batches of single-use codes for a subscription's
// offer code, generated by App Store Connect and written to a CSV file.
//
// Deliberately not part of `release`: every batch spends codes from Apple's
// quota and puts redeemable codes on disk, so it runs only when asked. Matched
// by count, expiry and environment — re-running generates nothing new, and only
// downloads a batch again when its file is missing.

import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { dirname } from "node:path";

import { Status } from "../core/status.mjs";
import { finding, Severity, Category, FixOwner } from "../core/findings.mjs";
import { subscriptionConfigs } from "../core/products.mjs";
import { isGitIgnored } from "../core/git.mjs";

/** @type {import("./registry.mjs").OperationMeta} */
export const meta = {
  id: "offer-codes",
  title: "Offer code batches",
  phase: "listing",
  needs: [],
  mutates: true,
};

/** @param {import("../core/context.mjs").Context} ctx */
export async function run(ctx) {
  const { client, discovery, config, resolvePath, projectRoot } = ctx;
  const wanted = subscriptionConfigs(config).flatMap((product) =>
    /** @type {any[]} */ (/** @type {any} */ (product).offerCodes ?? []).flatMap((offer) =>
      (offer.oneTimeCodes ?? []).map((/** @type {any} */ batch) => ({ product, offer, batch })),
    ),
  );
  if (!wanted.length) return { status: Status.SKIPPED, message: "no oneTimeCodes configured" };

  const r = await client.get(`/v1/apps/${discovery.appId}/subscriptionGroups?include=subscriptions&limit=50`);
  const subs = (r.included ?? []).filter((x) => x.type === "subscriptions");

  /** @type {import("../core/findings.mjs").Finding[]} */
  const findings = [];
  const changes = [];
  /** @type {Map<string, any[]>} */
  const codesBySub = new Map();

  for (const { product, offer, batch } of wanted) {
    const label = `"${offer.name}" (${batch.count}, until ${batch.expires})`;
    const sub = subs.find((s) => s.attributes?.productId === product.productId);
    if (!sub) {
      findings.push(
        notYet(`${product.productId} does not exist in App Store Connect`, "appstore-release subscription"),
      );
      continue;
    }
    if (!codesBySub.has(sub.id))
      codesBySub.set(sub.id, await client.all(`/v1/subscriptions/${sub.id}/offerCodes`, { limit: 200 }));
    const code = codesBySub.get(sub.id)?.find((c) => c.attributes?.name === offer.name);
    if (!code) {
      findings.push(notYet(`Offer code "${offer.name}" does not exist yet`, "appstore-release subscription"));
      continue;
    }

    const environment = batch.environment ?? "PRODUCTION";
    const batches = await client.all(`/v1/subscriptionOfferCodes/${code.id}/oneTimeUseCodes`, { limit: 200 });
    let made = batches.find(
      (b) =>
        b.attributes?.numberOfCodes === batch.count &&
        b.attributes?.expirationDate === batch.expires &&
        (b.attributes?.environment ?? "PRODUCTION") === environment,
    );
    if (!made) {
      made = (
        await client.post(`/v1/subscriptionOfferCodeOneTimeUseCodes`, {
          data: {
            type: "subscriptionOfferCodeOneTimeUseCodes",
            attributes: { numberOfCodes: batch.count, expirationDate: batch.expires, environment },
            relationships: { offerCode: { data: { type: "subscriptionOfferCodes", id: code.id } } },
          },
        })
      ).data;
      changes.push(`generated ${label}`);
    }

    const out = resolvePath(batch.output, `offerCodes.${offer.name}.oneTimeCodes.output`);
    if (!existsSync(out)) {
      if (String(made.id).startsWith("dry:")) {
        changes.push(`would write ${batch.output}`);
      } else {
        // Apple generates a batch in the background; its values may not be ready yet.
        const values = await client.get(`/v1/subscriptionOfferCodeOneTimeUseCodes/${made.id}/values`, {
          text: true,
          throwOnError: false,
        });
        if ("error" in values || !values.text) {
          findings.push(
            finding({
              id: `offer-codes.not-ready.${offer.name}`,
              severity: Severity.INFO,
              category: Category.ASC_STATE,
              title: `The codes for ${label} are not ready to download yet`,
              detail: "App Store Connect generates a batch in the background. It exists; only the file is missing.",
              fixOwner: FixOwner.CLI,
              fix: "Run offer-codes again in a few minutes.",
              fixCommand: "appstore-release offer-codes",
            }),
          );
          continue;
        }
        mkdirSync(dirname(out), { recursive: true });
        writeFileSync(out, values.text, { mode: 0o600 });
        changes.push(`wrote ${batch.output}`);
      }
    }
    if (existsSync(out) && !isGitIgnored(out, projectRoot)) {
      findings.push(
        finding({
          id: `offer-codes.not-ignored.${offer.name}`,
          severity: Severity.WARNING,
          category: Category.CONFIG,
          title: `${batch.output} holds redeemable codes and is not ignored by git`,
          detail: "Anyone who can read the repository could redeem them.",
          fixOwner: FixOwner.EXTERNAL,
          fix: `Add ${batch.output} to .gitignore.`,
        }),
      );
    }
  }

  const blocked = findings.filter((f) => f.severity === Severity.BLOCKER);
  return {
    status: blocked.length ? Status.ERROR : changes.length ? Status.CHANGED : Status.OK,
    message: changes.length
      ? changes.join(" · ")
      : blocked.length
        ? blocked[0].title
        : "every batch is generated and saved",
    findings,
  };
}

/** @param {string} what @param {string} command */
function notYet(what, command) {
  return finding({
    id: "offer-codes.offer-missing",
    category: Category.ASC_STATE,
    title: what,
    detail: "One-time codes belong to an offer code, which the subscription step creates from the config.",
    fix: "Run the subscription step first.",
    fixCommand: command,
  });
}
